window.hello_r_buy = (options, cb) => {
       if (!options) {
           console.warn("no options");
           return
       }
       if (!options.id || !options.refId) {
           console.warn("no id or refid");
           return
       }
       if (!options.quantity) {
           options.quantity = 1;
       }
       if (!options.removable) {
           options.removable = true;
       }
       Wtheme.api.post("/store-api/checkout/cart/line-item", JSON.stringify({
           items: [{
               "referencedId": options.refId,
               "id": options.id,
               "type": "product",
               "quantity": options.quantity,
               "removable": true
           }]
       }), () => {document.getElementsByClassName("header-cart-btn")[0].click();})
   }

window.dataLayer = window.dataLayer || [];
function gtag() { dataLayer.push(arguments); }

(() => {
    const analyticsStorageEnabled = document.cookie.split(';').some((item) => item.trim().includes('google-analytics-enabled=1'));
    const adsEnabled = document.cookie.split(';').some((item) => item.trim().includes('google-ads-enabled=1'));

    // Always set a default consent for consent mode v2
    gtag('consent', 'default', {
        'ad_user_data': adsEnabled ? 'granted' : 'denied',
        'ad_storage': adsEnabled ? 'granted' : 'denied',
        'ad_personalization': adsEnabled ? 'granted' : 'denied',
        'analytics_storage': analyticsStorageEnabled ? 'granted' : 'denied'
    });
})();

